const { createdAfter, createdBefore, limit, startingAfter, expand } = $.input;

const params = {};
if (createdAfter) params['created[gte]'] = String(createdAfter);
if (createdBefore) params['created[lte]'] = String(createdBefore);
if (limit) params.limit = String(Math.max(1, Math.min(100, limit)));
if (startingAfter) params.starting_after = startingAfter;

if (expand && expand.length > 0) {
  expand.forEach((field, i) => {
    params[`expand[${i}]`] = field;
  });
}

return { params };

const resp = $.steps.listAccounts.response || {};
const accounts = resp.data || [];

function deleteNested(obj, path) {
  const parts = path.split('.');
  let current = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    if (!current || typeof current !== 'object') return;
    current = current[parts[i]];
  }
  if (current && typeof current === 'object') {
    delete current[parts[parts.length - 1]];
  }
}

const keysToRemove = [
  'business_profile.annual_revenue', 'business_profile.estimated_worker_count',
  'business_profile.support_address', 'business_profile.support_email',
  'business_profile.support_phone', 'business_profile.support_url',
  'controller.fees', 'controller.losses', 'controller.requirement_collection',
  'controller.stripe_dashboard',
  'external_accounts.has_more', 'external_accounts.total_count', 'external_accounts.url',
  'future_requirements.alternatives', 'future_requirements.current_deadline',
  'future_requirements.disabled_reason', 'future_requirements.errors',
  'future_requirements.past_due', 'future_requirements.pending_verification',
  'login_links',
  'requirements.alternatives', 'requirements.current_deadline',
  'requirements.errors', 'requirements.pending_verification',
  'settings.bacs_debit_payments', 'settings.branding', 'settings.card_issuing',
  'settings.card_payments.decline_on', 'settings.card_payments.statement_descriptor_prefix',
  'settings.card_payments.statement_descriptor_prefix_kanji',
  'settings.card_payments.statement_descriptor_prefix_kana',
  'settings.dashboard.display_name', 'settings.dashboard.timezone',
  'settings.invoices',
  'settings.payments.statement_descriptor', 'settings.payments.statement_descriptor_kana',
  'settings.payments.statement_descriptor_kanji',
  'settings.payouts.debit_negative_balances', 'settings.payouts.schedule',
  'settings.payouts.statement_descriptor', 'settings.sepa_debit_payments',
  'tos_acceptance.service_agreement', 'tos_acceptance.user_agent'
];

const compressed = accounts.map(account => {
  const c = JSON.parse(JSON.stringify(account));
  keysToRemove.forEach(path => deleteNested(c, path));
  return c;
});

return {
  accounts: compressed,
  totalReturned: compressed.length,
  hasMore: resp.has_more || false,
  summary: `Retrieved ${compressed.length} connected account${compressed.length === 1 ? '' : 's'}`
};
